scenarios.example_code:
import { putSecret } from '@projexlight/sdk-secrets';
const { ref } = await putSecret({
  tenant_id, name: 'snowflake-prod-svc',
  plaintext: privateKeyPem,
  purpose: 'connector-snowflake',
});
// Persist `ref` in the connector install row instead of the key.

import { getSecret } from '@projexlight/sdk-secrets';
const plaintext = await getSecret({ ref, caller_sdk: '@projexlight/connector-snowflake' });
const session = await snowflake.connect({ privateKey: plaintext });
// plaintext goes out of scope immediately after.

import { rotateSecret } from '@projexlight/sdk-secrets';
const { new_version } = await rotateSecret({
  ref, new_plaintext: newPrivateKeyPem,
  grace_hours: 24,
});

subscribeEvents('tenant.offboarded.v1', async (e) => {
  await retireAllSecretsForTenant({ tenant_id: e.payload.tenant_id, reason: 'tenant-offboarded' });
});

// rate-limit fires automatically in getSecret; alert path:
subscribeEvents('secrets.secret.read.v1', async (e) => {
  const c = await getRecentReadCount({ persona_id: e.payload.persona_id, window_sec: 60 });
  if (c > 50) alertOps({ persona_id: e.payload.persona_id, count: c });
});
